package com.citacloud.app.controllers; import com.citacloud.app.security.AuthService; import com.citacloud.app.services.DocumentoService; import org.springframework.core.io.FileSystemResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/documentos") public class DocumentoController {private final DocumentoService service;public DocumentoController(DocumentoService s){service=s;}@GetMapping("/{id}") public ResponseEntity<FileSystemResource> descargar(@PathVariable UUID id){var user=AuthService.getAuthenticatedUser();if(user==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();try{var doc=service.obtener(user.getEmpresaId(),id);Path ruta=service.ruta(doc);if(!ruta.startsWith(ruta.getParent().getParent().getParent())||!Files.isRegularFile(ruta))return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(doc.getTipo())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+doc.getNombreArchivo().replace("\"","")+"\"").body(new FileSystemResource(ruta));}catch(Exception e){return ResponseEntity.notFound().build();}}}
